(() => {
'use strict';
const params=new URLSearchParams(location.search),store=window.GALLERY_CATALOGUE,mirrors=window.MIRROR_PRODUCTS||[];
if(!store)return;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=(dept,sub='')=>'catalogue.html?'+new URLSearchParams({dept,...(sub?{sub}:{})});
const fields={'Product Type':'type','Type':'type','Availability':'availability','Colour & Finish':'colour','Colour':'colour','Material':'material','Width or Size':'size','Height or Size':'size','Size':'size','Collection':'collection','Art Type':'type','Frame Material':'material'};
const values=(p,key)=>{const value=p[fields[key]||key];return Array.isArray(value)?value:value?[value]:[]};
const normalize=v=>String(v).toLowerCase().replace(/ collection$| clocks$| mirrors$/g,'').replace(/[^a-z0-9]/g,'');
function routeMatch(p,sub){const q=normalize(sub);if(p.dept==='Clocks'&&window.VersionBFilters&&window.ClocksFilters.values(p,'type').some(v=>normalize(v)===q))return true;if(p.dept==='Outdoor Living'){const outdoor={diningsets:['Dining Set','Dining Sets'],loungesets:['Lounge Set','Lounge Sets'],bistrotablessets:['Bistro Tables','Bistro Sets','Bistro Tables and Sets','Bistro Tables & Sets'],barsets:['Bar Set','Bar Sets'],chairs:['Chairs','Outdoor Chairs'],sofas:['Sofas','Outdoor Sofas'],stools:['Stool','Stools'],tables:['Tables','Outdoor Tables'],sidetables:['Side Tables','Outdoor Side Tables'],drinkstrolleys:['Drinks Trolley','Drinks Trolleys'],outdoormirrors:['Mirrors','Outdoor Mirrors']};if(outdoor[q])return outdoor[q].includes(p.type);}if(q==='designseries')return values(p,'Collection').some(v=>normalize(v)==='designseries');const aggregates={kitchentextiles:['Kitchen Apron','Aprons','Kitchen Oven Glove','Oven Gloves','Tea Towel','Tea Towels'],tablelinen:['Napkin','Napkins','Placemat','Placemats','Table Cloth','Tablecloths','Table Runner','Table Runners'],seatbenchpads:['Bench Pads','Seat and Bench Pads','Seat & Bench Pads'],duvetspillows:['Duvets','Pillows','Duvets and Pillows','Duvets & Pillows'],protectorstoppers:['Protectors','Toppers','Protectors and Toppers','Protectors & Toppers'],doormats:['Doormat','Doormats'],outdoorcushionsthrows:['Outdoor Cushions','Outdoor Throws','Outdoor Cushions and Throws','Outdoor Cushions & Throws'],ceilinglighting:['Ceiling Lighting','Ceiling Lights','Pendants','Chandeliers','Flush & Semi-flush'],pendantlighting:['Pendants','Pendant Lighting'],shadesandbases:['Lamp Shades','Lamp Bases','Shades and Bases'],spotlights:['Spot Lights','Spotlights'],wallfitting:['Wall Fitting','Wall Fittings'],potsplanters:['Planters','Pots','Pots & Planters'],ornamentssculptures:['Decorative Objects','Ornaments','Sculptures'],glasswarebarware:['Glassware','Barware'],coastersplacemats:['Coasters','Kitchen Placemats','Placemats'],candleholderslanterns:['Candle Holders','Lanterns'],boxesbaskets:['Boxes','Baskets','Baskets & Storage'],roomsprays:['Room Spray','Room Sprays'],doorstops:['Doorstop','Doorstops'],ceilinglights:['Pendants','Chandeliers','Flush & Semi-flush'],bookcasesshelving:['Bookcases','Shelving Units','Bookcases and Shelving Units'],parasolbases:['Bases','Parasol Bases'],armchairsaccentchairs:['Armchairs & Accent Chairs','Armchairs','Accent Chairs'],chestsofdrawers:['Chest of Drawers','Chests of Drawers']};if(aggregates[q])return aggregates[q].includes(p.type);const alias={armchairs:'armchairsaccentchairs',sidetables:'sidelamptables',candleware:'candleholders',traysstorage:'trays',plain:'plain',patterned:'patterned'};const target=alias[q]||q;if(['newclocks','newlighting','newaccessories','collections','more'].includes(q))return false;return Object.values(p).flat().some(v=>typeof v==='string'&&normalize(v)===target)}
window.GalleryCatalogueRouting={routeMatch,values};
if(!$('#mirror-grid')){
 const sku=params.get('sku'),found=store.products.find(p=>p.sku===sku);
 if(found){window.MIRROR_PRODUCTS=[...mirrors,...store.products];window.CATALOGUE_CONTEXT={product:found};}
 return;
}
const search=params.get('search')||params.get('q')||'',dept=params.get('dept')||'Furniture',sub=params.get('sub')||'',group=params.get('group')||'',route=params.get('route')||'';
let base=search&&!params.has('dept')?[...mirrors,...store.products]:store.products.filter(p=>p.dept===dept);
if(dept==='Mirrors'){const target=new URL('mirrors.html',location.href);for(const [key,value] of params)if(key!=='dept')target.searchParams.set(key,value);location.replace(target.href);return;}
if(group){const names=store.departments[dept]?.groups.find(g=>g[0]===group)?.slice(1)||[];base=base.filter(p=>names.some(name=>routeMatch(p,name)));}
if(sub&&!sub.startsWith('All '))base=base.filter(p=>routeMatch(p,sub));
if(route)base=[];
const menuRoute=window.VersionBMegaRoutes?.resolve(dept,params,base);if(menuRoute)base=menuRoute.products;
const config=store.departments[dept];let title=route||sub||group||(dept==='Greeting Cards'?'Greeting Cards':dept);if(menuRoute)title=menuRoute.title;if(search&&!params.has('dept'))title='Search products';
const heroImages={'Furniture':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_Furn.jpg','Lighting':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_Lighting.jpg','Outdoor Living':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_Outdoor.jpg','Home Accessories':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_Acc.jpg','Soft Furnishings':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_Textiles.jpg','Mattresses':'assets/9076618d825d9515.webp','Made to Order':'https://www.gallerydirect.co.uk/media/wysiwyg/2606_Homepage_MTO.jpg','Clocks':'images/clocks-category.png','Art':'assets/0efb58f76d1d4cf0.webp','Greeting Cards':'assets/7f43ef3ecab733db.webp'};
window.MIRROR_PRODUCTS=base;
let keys=search&&!params.has('dept')?['Product Type','Availability','Colour','Material','Size','Collection']:(config?.filters||['Product Type','Availability']);
if(dept==='Clocks')keys=[...keys,'Availability'];
if(sub==='Photo Frames')keys=['Photo Size','Colour & Finish','Frame Material','Display Type','Orientation','Availability'];
const labels={};for(const key of keys){if(key==='Trade Price')continue;const property=fields[key]||key;if(base.some(p=>values(p,key).some(v=>v&&v!=='Not specified'&&v!=='Not supplied')))labels[property]=key;}
if(dept==='Soft Furnishings')labels.type='Product Type';
window.CATALOGUE_CONTEXT={dept,sub,group,title,labels,search,route,facetOptions:dept==='Soft Furnishings'?{type:(sub==='Kitchen Textiles'?['Aprons','Oven Gloves','Tea Towels']:sub==='Table Linen'?['Napkins','Placemats','Tablecloths','Table Runners']:group?config.groups.find(g=>g[0]===group).slice(1):config.groups.flatMap(g=>g.slice(1))).flatMap(n=>n==='Kitchen Textiles'?['Aprons','Oven Gloves','Tea Towels']:n==='Table Linen'?['Napkins','Placemats','Tablecloths','Table Runners']:[n])}:undefined};
if(dept==='Furniture'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.FurnitureFilters.configure(base,sub,group));
if(dept==='Art'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.ArtFilters.configure(base));
if(dept==='Lighting'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.LightingFilters.configure(base,sub));
if(dept==='Lighting'&&base.some(p=>p.demoLighting))window.CATALOGUE_CONTEXT.filterNote='Demo specifications and availability only. Replace with verified Gallery data before ordering.';
if(dept==='Soft Furnishings'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.TextilesFilters.configure(base,sub,group));
if(dept==='Home Accessories'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.AccessoriesFilters.configure(base,sub,group));
if(dept==='Greeting Cards'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.ArtbeatFilters.configure(base));
if(dept==='Made to Order'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.MadeToOrderFilters.configure(base,sub));
if(dept==='Clocks'&&!(search&&!params.has('dept')))Object.assign(window.CATALOGUE_CONTEXT,window.ClocksFilters.configure(base));
document.title=title+' | Gallery Direct Preview';$('#category-title').textContent=title;$('#category-kicker').textContent=dept==='Greeting Cards'?'Artbeat':(sub||group)?dept:'Gallery Direct';$('#category-description').textContent=dept==='Greeting Cards'?'Browse Artbeat greeting cards by occasion and collection.':route?'This collection needs approved range data before products can be shown.':config?.desc||'Browse the available sample products.';
$('#category-hero-image').addEventListener('error',e=>e.currentTarget.hidden=true);$('#category-hero-image').src=heroImages[dept]||heroImages.Furniture;
$('#category-breadcrumbs').innerHTML='<a href="index.html">Home</a><span>/</span>'+((sub||group)?`<a href="${url(dept)}">${esc(dept)}</a><span>/</span>`:'')+`<strong>${esc(title)}</strong>`;
$('.subcategory-strip').innerHTML=`<a href="${url(dept)}" class="${!sub&&!group?'is-active':''}">All ${esc(dept)}</a>`+(config?.groups||[]).flatMap(([heading,...items])=>items).map(label=>`<a href="${url(dept,label)}" class="${label===sub?'is-active':''}">${esc(label)}</a>`).join('');
if($('.preview-notice'))$('.preview-notice').textContent='Interactive preview · sample range · Gallery trade prices and availability require verification.';
const seo=$('.seo-category-copy');if(seo){seo.innerHTML=`<div><div class="kicker">Gallery Direct</div><h2>Explore ${esc(dept)}</h2></div><div><p>${esc(config?.desc||'Browse the available sample range.')}</p><div class="seo-links"><a href="${url(dept)}">All ${esc(dept)}</a><a href="index.html">Shop by department</a></div></div>`;}
})();
